import { useEffect,useMemo,useState } from 'react'
import { Link,useLocation,useNavigate } from 'react-router-dom'
import { storeData,styles,money,getItem,getBrand,getRoot } from './industryStoreData.js'
import './industryStorefront.css'

const to=(ctx,part='')=>ctx.root+(part?'/'+part:'')
const imageFallback=(ctx)=>ctx.store.secondary||ctx.store.hero
function Pic({src,alt,fallback, ...props}) {
 const [bad,setBad]=useState(false)
 useEffect(()=>setBad(false),[src])
 return <img {...props} loading="lazy" decoding="async" src={bad?(fallback||src):src} alt={alt} onError={()=>setBad(true)}/>
}
function Mark({name,size=19}) {
 const shapes={arrow:'M5 12h14m-5-5 5 5-5 5',bag:'M4 8h16l1 13H3L4 8ZM8 9V6a4 4 0 0 1 8 0v3',heart:'M20.8 4.7a5.5 5.5 0 0 0-7.8 0L12 5.8l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.5a5.5 5.5 0 0 0 0-7.8Z',search:'M21 21l-4.5-4.5M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',menu:'M4 6h16M4 12h16M4 18h16',close:'M5 5l14 14M19 5 5 19',plus:'M12 5v14M5 12h14',check:'M5 12l5 5 14-14',sparkle:'m12 2 2 7 7 2-7 2-2 7-2-7-7-2 7-2 2-7',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM12 7v5l3 2',calendar:'M4 5h16v16H4V5ZM8 2v6M16 2v6M4 10h16'}
 return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={shapes[name]||shapes.sparkle}/></svg>
}
function useShop(ctx){
 const key='qing-sample-'+ctx.store.slug+'-'+ctx.style
 const [saved,setSaved]=useState(()=>{try{return JSON.parse(localStorage.getItem(key+'-saved')||'[]')}catch{return []}})
 const [cart,setCart]=useState(()=>{try{return JSON.parse(localStorage.getItem(key+'-cart')||'[]')}catch{return []}})
 const [drawer,setDrawer]=useState(false)
 useEffect(()=>{try{localStorage.setItem(key+'-saved',JSON.stringify(saved))}catch{}},[key,saved])
 useEffect(()=>{try{localStorage.setItem(key+'-cart',JSON.stringify(cart))}catch{}},[key,cart])
 const toggle=id=>setSaved(c=>c.includes(id)?c.filter(x=>x!==id):[...c,id])
 const add=(p,color='Original',qty=1)=>{
  const k=p.id+'-'+color
  setCart(c=>c.some(x=>x.key===k)?c.map(x=>x.key===k?{...x,quantity:x.quantity+qty}:x):[...c,{key:k,id:p.id,title:p.title,price:p.price,image:p.image,color,quantity:qty}])
  setDrawer(true)
 }
 const change=(k,d)=>setCart(c=>c.map(x=>x.key===k?{...x,quantity:x.quantity+d}:x).filter(x=>x.quantity>0))
 const remove=k=>setCart(c=>c.filter(x=>x.key!==k))
 const total=cart.reduce((n,p)=>n+p.quantity*p.price,0)
 const count=cart.reduce((n,p)=>n+p.quantity,0)
 return {saved,cart,drawer,setDrawer,toggle,add,change,remove,total,count}
}
function Header({ctx,shop}){
 const [menu,setMenu]=useState(false)
 const location=useLocation()
 const slug=ctx.store.slug
 const links=slug==='beauty'?[['Services','explore'],['Book now','book'],['Our story','about'],['Contact','contact']]
 :slug==='events'?[['Our work','explore'],['Plan an event','plan'],['Our studio','about'],['Contact','contact']]
 :slug==='accessories'?[['The collection','explore'],['Style kit','style-kit'],['About','about'],['Contact','contact']]
 :[['Explore stays','explore'],['Find a stay','search'],['Our story','about'],['Contact','contact']]
 return <header className="ix-header" id="ix-top"><Link to={ctx.root} className="ix-brand">{ctx.style==='editorial'&&<span className="ix-brand-symbol">·</span>}<span>{ctx.brand.name}<small>{ctx.brand.eyebrow}</small></span></Link>
 <nav className={'ix-nav-links '+(menu?'open':'')} aria-label={ctx.store.label+' navigation'}>{links.map(([label,route])=><Link key={route} className={location.pathname===to(ctx,route)?'active':''} to={to(ctx,route)} onClick={()=>setMenu(false)}>{label}</Link>)}<Link className="ix-mobile-extra" to={to(ctx,'faq')} onClick={()=>setMenu(false)}>FAQs</Link></nav>
 <div className="ix-nav-right"><Link to={to(ctx,'saved')} className="ix-iconbtn" aria-label={'Saved favourites: '+shop.saved.length}><Mark name="heart"/>{shop.saved.length>0&&<sup>{shop.saved.length}</sup>}</Link>{slug==='accessories'?<button className="ix-iconbtn" onClick={()=>shop.setDrawer(true)} aria-label={'Open bag, '+shop.count+' items'}><Mark name="bag"/><sup>{shop.count}</sup></button>:<Link className="ix-header-cta" to={to(ctx,slug==='beauty'?'book':slug==='events'?'plan':'search')}>{slug==='beauty'?'Book a session':slug==='events'?'Make an enquiry':'Find your stay'}</Link>}<button className="ix-menu" onClick={()=>setMenu(!menu)} aria-label="Toggle navigation" aria-expanded={menu}><Mark name={menu?'close':'menu'}/></button></div></header>
}
function Heading({eyebrow,children,ctx,link='explore'}){
 return <div className="ix-section-heading"><div><span>{eyebrow}</span><h2>{children}</h2></div><Link to={to(ctx,link)}>Discover more <Mark name="arrow" size={16}/></Link></div>
}
function Chip({children}){return <span className="ix-chip">{children}</span>}
function Card({ctx,p,shop}){
 const selected=shop.saved.includes(p.id)
 return <article className="ix-product"><div className="ix-product-media"><Link to={to(ctx,'item/'+p.id)} aria-label={'View '+p.title}><Pic src={p.image} fallback={imageFallback(ctx)} alt={p.title+' illustrative photograph'}/></Link>{p.badge&&<span className="ix-photo-tag">{p.badge}</span>}<button className={'ix-heart '+(selected?'selected':'')} onClick={()=>shop.toggle(p.id)} aria-label={(selected?'Remove ':'Save ')+p.title} aria-pressed={selected}><Mark name="heart" size={17}/></button></div><div className="ix-product-meta"><span>{p.category}</span><Link to={to(ctx,'item/'+p.id)}><h3>{p.title}</h3></Link><p>{p.description}</p><div><strong>{money(p.price)}{ctx.store.slug==='hospitality'&&<small> / night</small>}{ctx.store.slug==='events'&&<small> · from</small>}</strong><Link to={to(ctx,'item/'+p.id)} aria-label={'View '+p.title}><Mark name="plus" size={17}/></Link></div></div></article>
}
function Cards({ctx,shop,items}){return <div className="ix-grid-cards">{items.map(p=><Card key={p.id} ctx={ctx} shop={shop} p={p}/>)}</div>}
function WideCTA({ctx,eyebrow,title,body,image,path,label}){
 return <section className="ix-wide-cta"><div><span>{eyebrow}</span><h2>{title}</h2><p>{body}</p><Link to={to(ctx,path)}>{label} <Mark name="arrow"/></Link></div><Pic src={image||ctx.store.secondary} fallback={ctx.store.hero} alt={title+' editorial visual'}/></section>
}
function FeatureLine({children}){return <div className="ix-ticker" aria-hidden="true"><span>{children} · {children} · {children}</span></div>}
function Showcase({ctx,shop,eyebrow='THE EDIT',label='Featured favourites'}){
 return <section className="ix-featured"><Heading ctx={ctx} eyebrow={eyebrow}>{label}</Heading><Cards ctx={ctx} shop={shop} items={ctx.store.items.slice(0,4)}/></section>
}
